import { handleAiRequest } from "../_shared/handler.ts";
import type { CompletionRequest } from "../_shared/provider.ts";

Deno.serve((req) =>
  handleAiRequest(req, {
    buildRequest: (body): CompletionRequest => ({
      prompt: typeof body.prompt === "string" ? body.prompt : undefined,
      response_json_schema: (body.response_json_schema || body.json_schema) as
        | Record<string, unknown>
        | undefined,
    }),
  })
);

import { createClient, type User } from "https://esm.sh/@supabase/supabase-js@2.49.1";

export type AuthResult =
  | { ok: true; user: User }
  | { ok: false; message: string; status: number };

function getEnv(name: string): string {
  const value = Deno.env.get(name);
  if (!value) throw new Error(`Missing required environment variable: ${name}`);
  return value;
}

export async function validateJwt(req: Request): Promise<AuthResult> {
  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return { ok: false, message: "Missing or invalid Authorization header.", status: 401 };
  }

  const token = authHeader.slice(7).trim();
  if (!token) {
    return { ok: false, message: "Missing bearer token.", status: 401 };
  }

  const supabase = createClient(
    getEnv("SUPABASE_URL"),
    getEnv("SUPABASE_SERVICE_ROLE_KEY"),
    { auth: { persistSession: false, autoRefreshToken: false } },
  );

  const { data, error } = await supabase.auth.getUser(token);
  if (error || !data.user) {
    return {
      ok: false,
      message: error?.message ?? "Invalid or expired JWT.",
      status: 401,
    };
  }

  return { ok: true, user: data.user };
}

const ADMIN_ROLES = new Set(["admin", "superadmin", "systemadmin", "supportadmin"]);

export function isAdminUser(user: User): boolean {
  const role = (
    user.app_metadata?.role ||
    user.user_metadata?.role ||
    user.user_metadata?.user_role ||
    ""
  ).toString().toLowerCase();
  return ADMIN_ROLES.has(role);
}

const DEFAULT_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

export function corsHeaders(extra: Record<string, string> = {}): HeadersInit {
  return { ...DEFAULT_HEADERS, ...extra };
}

export function handleCors(req: Request): Response | null {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: corsHeaders() });
  }
  return null;
}

export function jsonResponse(
  body: unknown,
  status = 200,
  extra: Record<string, string> = {},
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders(),
      "Content-Type": "application/json",
      ...extra,
    },
  });
}

export type AiUsage = {
  prompt_tokens?: number;
  completion_tokens?: number;
  total_tokens?: number;
};

export type EdgeError = {
  code: string;
  message: string;
  retryable?: boolean;
  details?: unknown;
};

export type EdgeEnvelope<T = unknown> = {
  success: boolean;
  result: T | null;
  error: EdgeError | null;
  provider: string | null;
  model: string | null;
  latency: number;
  usage: AiUsage | null;
  metadata: Record<string, unknown>;
};

export function successEnvelope<T>(
  params: {
    result: T;
    provider?: string | null;
    model?: string | null;
    latency?: number;
    usage?: AiUsage | null;
    metadata?: Record<string, unknown>;
  },
): EdgeEnvelope<T> {
  return {
    success: true,
    result: params.result,
    error: null,
    provider: params.provider ?? null,
    model: params.model ?? null,
    latency: params.latency ?? 0,
    usage: params.usage ?? null,
    metadata: params.metadata ?? {},
  };
}

export function errorEnvelope(
  message: string,
  params: {
    code?: string;
    provider?: string | null;
    model?: string | null;
    latency?: number;
    retryable?: boolean;
    details?: unknown;
    metadata?: Record<string, unknown>;
  } = {},
): EdgeEnvelope<null> {
  return {
    success: false,
    result: null,
    error: {
      code: params.code ?? "EDGE_FUNCTION_ERROR",
      message,
      retryable: params.retryable ?? false,
      details: params.details,
    },
    provider: params.provider ?? null,
    model: params.model ?? null,
    latency: params.latency ?? 0,
    usage: null,
    metadata: params.metadata ?? {},
  };
}

import { handleCors, jsonResponse } from "./cors.ts";
import { validateJwt } from "./auth.ts";
import { errorEnvelope, successEnvelope } from "./envelope.ts";
import {
  complete,
  type CompletionRequest,
  type CompletionResult,
} from "./provider.ts";

export type AiHandlerOptions = {
  requireAuth?: boolean;
  mapResult?: (completion: CompletionResult, body: Record<string, unknown>) => unknown;
  buildRequest?: (body: Record<string, unknown>) => CompletionRequest;
  /** Adds Base44-compatible `status` + `output` fields for document extraction. */
  documentLegacyShape?: boolean;
  /** Returns chunked text when `stream: true` (client stub). */
  streamStub?: boolean;
};

export async function handleAiRequest(
  req: Request,
  options: AiHandlerOptions = {},
): Promise<Response> {
  const cors = handleCors(req);
  if (cors) return cors;

  if (req.method !== "POST") {
    return jsonResponse(errorEnvelope("Method not allowed.", { code: "METHOD_NOT_ALLOWED" }), 405);
  }

  const started = Date.now();

  try {
    if (options.requireAuth !== false) {
      const auth = await validateJwt(req);
      if (!auth.ok) {
        return jsonResponse(
          errorEnvelope(auth.message, { code: "AI_AUTHENTICATION", latency: Date.now() - started }),
          auth.status,
        );
      }
    }

    const body = await req.json() as Record<string, unknown>;
    const completionReq = options.buildRequest
      ? options.buildRequest(body)
      : body as CompletionRequest;

    if (!completionReq.prompt && !completionReq.messages?.length && !completionReq.file_url && !completionReq.file_urls?.length) {
      return jsonResponse(
        errorEnvelope("prompt, messages, or file_url(s) required.", {
          code: "INVALID_REQUEST",
          latency: Date.now() - started,
        }),
        400,
      );
    }

    const completion = await complete(completionReq);
    const result = options.mapResult
      ? options.mapResult(completion, body)
      : completion.parsed ?? completion.text;

    const envelope: Record<string, unknown> = successEnvelope({
      result,
      provider: completion.provider,
      model: completion.model,
      latency: Date.now() - started,
      usage: completion.usage,
      metadata: { function: "ai" },
    });

    if (options.documentLegacyShape) {
      envelope.status = "success";
      envelope.output = result;
    }

    if (options.streamStub && body.stream) {
      const text = typeof result === "string" ? result : JSON.stringify(result);
      envelope.chunks = [text];
      envelope.result = text;
    }

    return jsonResponse(envelope);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const retryable = Boolean((error as Error & { retryable?: boolean }).retryable);
    const code = message.includes("429")
      ? "AI_RATE_LIMIT"
      : message.includes("401") || message.includes("403")
      ? "AI_AUTHENTICATION"
      : "AI_PROVIDER_ERROR";

    return jsonResponse(
      errorEnvelope(message, {
        code,
        retryable,
        latency: Date.now() - started,
        provider: Deno.env.get("AI_PROVIDER") || "openai",
      }),
      code === "AI_RATE_LIMIT" ? 429 : 500,
    );
  }
}

export function documentResult(completion: CompletionResult): Record<string, unknown> {
  const output = completion.parsed ?? completion.text;
  return { status: "success", output };
}

import type { AiUsage } from "./envelope.ts";

export type AiProviderName = "openai" | "openrouter";

export type CompletionRequest = {
  prompt?: string;
  messages?: Array<{ role: string; content: unknown }>;
  file_url?: string;
  file_urls?: string[];
  json_schema?: Record<string, unknown>;
  response_json_schema?: Record<string, unknown>;
  stream?: boolean;
  model?: string;
};

export type CompletionResult = {
  text: string;
  parsed: unknown;
  model: string;
  provider: AiProviderName;
  usage: AiUsage | null;
};

type ProviderConfig = {
  name: AiProviderName;
  apiKey: string;
  baseUrl: string;
  defaultModel: string;
};

function resolveProvider(): ProviderConfig {
  const requested = (Deno.env.get("AI_PROVIDER") || "openai").toLowerCase();

  if (requested === "openrouter") {
    const apiKey = Deno.env.get("OPENROUTER_API_KEY");
    if (!apiKey) throw new Error("OPENROUTER_API_KEY is not configured.");
    return {
      name: "openrouter",
      apiKey,
      baseUrl: "https://openrouter.ai/api/v1",
      defaultModel: Deno.env.get("AI_MODEL") || "openai/gpt-4o",
    };
  }

  const apiKey = Deno.env.get("OPENAI_API_KEY");
  if (!apiKey) throw new Error("OPENAI_API_KEY is not configured.");
  return {
    name: "openai",
    apiKey,
    baseUrl: "https://api.openai.com/v1",
    defaultModel: Deno.env.get("AI_MODEL") || "gpt-4o",
  };
}

function schemaFromRequest(req: CompletionRequest): Record<string, unknown> | null {
  return (req.response_json_schema || req.json_schema || null) as Record<string, unknown> | null;
}

function buildUserContent(req: CompletionRequest): unknown {
  const urls = [
    ...(req.file_urls ?? []),
    ...(req.file_url ? [req.file_url] : []),
  ];

  const parts: Array<Record<string, unknown>> = [];
  if (req.prompt) parts.push({ type: "text", text: req.prompt });

  for (const url of urls) {
    parts.push({ type: "image_url", image_url: { url } });
  }

  if (parts.length === 0) return req.prompt ?? "";
  if (parts.length === 1 && parts[0].type === "text") return parts[0].text;
  return parts;
}

function buildMessages(req: CompletionRequest): Array<{ role: string; content: unknown }> {
  if (req.messages?.length) return req.messages;
  return [{ role: "user", content: buildUserContent(req) }];
}

function parseJsonText(text: string): unknown {
  const trimmed = text.trim();
  if (!trimmed) return null;
  try {
    return JSON.parse(trimmed);
  } catch {
    const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (fenced?.[1]) {
      try {
        return JSON.parse(fenced[1].trim());
      } catch {
        return trimmed;
      }
    }
    return trimmed;
  }
}

async function callChatCompletions(
  config: ProviderConfig,
  req: CompletionRequest,
): Promise<CompletionResult> {
  const schema = schemaFromRequest(req);
  const model = req.model || config.defaultModel;
  const messages = buildMessages(req).map((message) => ({
    role: message.role,
    content: message.content,
  }));

  const body: Record<string, unknown> = {
    model,
    messages,
    temperature: 0.2,
  };

  if (schema) {
    body.response_format = { type: "json_object" };
    const systemIdx = messages.findIndex((m) => m.role === "system");
    const schemaHint =
      `Respond with valid JSON matching this schema: ${JSON.stringify(schema)}`;
    if (systemIdx >= 0 && typeof messages[systemIdx].content === "string") {
      messages[systemIdx].content = `${messages[systemIdx].content}\n\n${schemaHint}`;
    } else {
      messages.unshift({ role: "system", content: schemaHint });
    }
    body.messages = messages;
  }

  const headers: Record<string, string> = {
    Authorization: `Bearer ${config.apiKey}`,
    "Content-Type": "application/json",
  };

  if (config.name === "openrouter") {
    headers["HTTP-Referer"] = Deno.env.get("OPENROUTER_HTTP_REFERER") || "https://boothbridge.app";
    headers["X-Title"] = Deno.env.get("OPENROUTER_APP_NAME") || "BoothBridge";
  }

  const response = await fetch(`${config.baseUrl}/chat/completions`, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const detail = await response.text();
    const retryable = response.status === 429 || response.status >= 500;
    const err = new Error(`Provider ${config.name} error (${response.status}): ${detail}`);
    (err as Error & { retryable?: boolean }).retryable = retryable;
    throw err;
  }

  const payload = await response.json();
  const text = payload?.choices?.[0]?.message?.content ?? "";
  const usage = payload?.usage
    ? {
      prompt_tokens: payload.usage.prompt_tokens,
      completion_tokens: payload.usage.completion_tokens,
      total_tokens: payload.usage.total_tokens,
    }
    : null;

  return {
    text,
    parsed: schema ? parseJsonText(text) : text,
    model: payload?.model || model,
    provider: config.name,
    usage,
  };
}

export async function complete(req: CompletionRequest): Promise<CompletionResult> {
  const config = resolveProvider();
  return callChatCompletions(config, req);
}

export async function probeProvider(): Promise<{
  provider: AiProviderName;
  model: string;
  ok: boolean;
  message?: string;
}> {
  try {
    const config = resolveProvider();
    const response = await fetch(`${config.baseUrl}/models`, {
      headers: { Authorization: `Bearer ${config.apiKey}` },
    });
    return {
      provider: config.name,
      model: config.defaultModel,
      ok: response.ok,
      message: response.ok ? "reachable" : `HTTP ${response.status}`,
    };
  } catch (error) {
    const config = resolveProvider();
    return {
      provider: config.name,
      model: config.defaultModel,
      ok: false,
      message: error instanceof Error ? error.message : String(error),
    };
  }
}

export function getActiveProviderName(): AiProviderName {
  return resolveProvider().name;
}

export function getDefaultModel(): string {
  return resolveProvider().defaultModel;
}
